(function(){"use strict";var LEAFLET_VERSION="1.9.4";var leafletPromise=null;function qs(id){return document.getElementById(id);}
function loadLeaflet(){if(window.L)return Promise.resolve(window.L);if(leafletPromise)return leafletPromise;leafletPromise=new Promise(function(resolve,reject){var css=document.createElement("link");css.rel="stylesheet";css.href="https://unpkg.com/leaflet@"+LEAFLET_VERSION+"/dist/leaflet.css";css.crossOrigin="anonymous";document.head.appendChild(css);var script=document.createElement("script");script.src="https://unpkg.com/leaflet@"+LEAFLET_VERSION+"/dist/leaflet.js";script.async=true;script.onload=function(){resolve(window.L);};script.onerror=function(){reject(new Error("Leaflet unavailable"));};document.head.appendChild(script);});return leafletPromise;}
function themeColor(name,fallback){var value=window.getComputedStyle(document.documentElement).getPropertyValue(name).trim();return value||fallback;}
function renderMap(map,points){if(map._visitorLayer)map.removeLayer(map._visitorLayer);var L=window.L;var accent=themeColor("--accent-500","#3b82f6");var accentStrong=themeColor("--accent-link-strong",accent);var layer=L.layerGroup();var maxWeight=points.reduce(function(max,point){return Math.max(max,point.weight||1);},1);points.forEach(function(point){var lat=Number(point.lat);var lon=Number(point.lon);if(!Number.isFinite(lat)||!Number.isFinite(lon)||lat<-90||lat>90||lon<-180||lon>180)return;var intensity=Math.max(0.28,Math.min(1,(point.weight||1)/maxWeight));var marker=L.circleMarker([lat,lon],{radius:7+intensity*10,color:accentStrong,weight:1.5,fillColor:accent,fillOpacity:0.34+intensity*0.48,});marker.bindTooltip((point.label||"Visitor location")+" · "+(point.weight||1)+" views",{direction:"top",opacity:0.95});layer.addLayer(marker);});layer.addTo(map);map._visitorLayer=layer;if(points.length){var bounds=L.latLngBounds(points.map(function(point){return[Number(point.lat),Number(point.lon)];}));if(bounds.isValid())map.fitBounds(bounds,{padding:[24,24],maxZoom:4});}else{map.setView([25,0],2);}}
function initLeafletMap(container,points){if(!window.L)return Promise.reject(new Error("Leaflet unavailable"));var map=container._visitorMap;if(!map){map=window.L.map(container,{worldCopyJump:true,minZoom:2,maxZoom:7,zoomControl:true,attributionControl:true});window.L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">OpenStreetMap contributors</a>',}).addTo(map);container._visitorMap=map;}
renderMap(map,points);window.setTimeout(function(){map.invalidateSize();},40);return Promise.resolve(map);}
function initVisitorStats(){var trigger=qs("visitorStatsTrigger");var popover=qs("visitorStatsPopover");var closeButton=qs("visitorStatsClose");var count=qs("totalViewsCount");var status=qs("visitorStatsStatus");var mapContainer=qs("visitorStatsMap");var controller=window.HomepageAnchoredPopover;if(!trigger||!popover||!closeButton||!count||!status||!mapContainer||!controller)return;var loaded=false;var loading=false;var closeTimer=0;var pinned=false;function loadStats(){if(loading||loaded)return;loading=true;Promise.all([fetch("/api/site/visits",{headers:{Accept:"application/json"},credentials:"same-origin"}).then(function(response){if(!response.ok)throw new Error("stats unavailable");return response.json();}),loadLeaflet(),]).then(function(results){var payload=results[0];count.textContent=Number(payload.total_views||0).toLocaleString();return initLeafletMap(mapContainer,Array.isArray(payload.points)?payload.points:[]).then(function(){status.textContent=payload.points&&payload.points.length?"Locations are grouped by city":"Location data is warming up";loaded=true;});}).catch(function(){status.textContent="Real map is temporarily unavailable";}).finally(function(){loading=false;});}
function clearClose(){if(closeTimer){window.clearTimeout(closeTimer);closeTimer=0;}}
function open(focusClose){clearClose();controller.open(popover,trigger,{placement:"top-end",initialFocus:focusClose?closeButton:null});loadStats();if(mapContainer._visitorMap)window.setTimeout(function(){mapContainer._visitorMap.invalidateSize();},30);}
function close(restore){clearClose();pinned=false;controller.close(popover,restore);}
function scheduleClose(){if(pinned)return;clearClose();closeTimer=window.setTimeout(function(){closeTimer=0;if(!trigger.matches(":hover")&&!popover.matches(":hover")&&trigger!==document.activeElement&&!popover.contains(document.activeElement))controller.close(popover,false);},180);}
trigger.addEventListener("pointerenter",function(event){if(event.pointerType!=="touch"){pinned=false;open(false);}});trigger.addEventListener("pointerleave",scheduleClose);trigger.addEventListener("focus",function(){open(false);});trigger.addEventListener("blur",scheduleClose);popover.addEventListener("pointerenter",clearClose);popover.addEventListener("pointerleave",scheduleClose);trigger.addEventListener("click",function(event){clearClose();if(controller.isOpen(popover)&&pinned){close(false);return;}
pinned=true;open(event.detail===0);});closeButton.addEventListener("click",function(){close(true);});loadStats();}
if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",initVisitorStats,{passive:true});else initVisitorStats();})();
